def search_glossary(question):
    # 用語名・別名の部分一致。短い英数字には単語境界を要求する。
    candidates=[]
    for term in glossary['terms']:
        for alias in [term['term']] + term.get('aliases', []):
            key=alias.casefold()
            if len(key) < 2:
                continue
            if re.fullmatch(r'[a-z0-9 -]+', key):
                match = re.search(r'(?<![a-z0-9])' + re.escape(key) + r'(?![a-z0-9])', question.casefold())
            else:
                match = key in question.casefold()
            if match:
                candidates.append((len(key),term))
    if not candidates:
        return {'id':None, 'answer':'用語集に該当項目が見つかりません。'}
    best=max(candidates,key=lambda pair:pair[0])[1]
    return {'id':best['id'], 'answer':best['definition']}

def glossary_generate(active_model, question):
    messages=[{'role':'user','content':question}]
    prompt=tok.apply_chat_template(messages, tokenize=False, add_generation_prompt=True, enable_thinking=False)
    inputs=tok(prompt,return_tensors='pt').to(active_model.device)
    with torch.no_grad():
        output=active_model.generate(**inputs, max_new_tokens=160, pad_token_id=tok.pad_token_id, do_sample=False)
    return tok.decode(output[0][inputs['input_ids'].shape[1]:],skip_special_tokens=True).strip()

